import re
import subprocess
import os
import psutil
from flask import Flask, request, jsonify

app = Flask(__name__)

@app.route('/monitor/commands', methods=['POST'])
def monitor_commands():
    data = request.get_json(silent=True)
    if not data:
        return jsonify({"code": 400, "message": "Invalid JSON body"}), 400

    if not isinstance(data, dict):
        return jsonify({"code": 400, "message": "JSON body must be an object"}), 400

    command_regex = data.get('command_regex')
    if not isinstance(command_regex, str) or not command_regex.strip():
        return jsonify({"code": 400, "message": "'command_regex' must be a non-empty string"}), 400

    filter_flags = data.get('filter_flags', '')
    if not isinstance(filter_flags, str):
        return jsonify({"code": 400, "message": "'filter_flags' must be a string"}), 400

    # Build ps command safely
    # We use ps -eo pid,args to get PID and full command line
    # Then filter by regex on the command line
    # ps aux shows user, but we don't need it; we just need PID and command
    # Using ps -eo pid,args --no-headers to avoid header issues
    cmd = ['ps', '-eo', 'pid,args', '--no-headers']
    try:
        result = subprocess.run(cmd, capture_output=True, text=True, timeout=10)
    except Exception as e:
        return jsonify({"code": 500, "message": f"Failed to run ps: {str(e)}"}), 500

    if result.returncode != 0:
        return jsonify({"code": 500, "message": f"ps failed: {result.stderr.strip()}"}), 500

    lines = result.stdout.strip().splitlines()
    matches = []
    pattern = re.compile(command_regex, re.IGNORECASE)

    for line in lines:
        # Split on first whitespace to separate PID and command
        parts = line.strip().split(maxsplit=1)
        if len(parts) < 2:
            continue
        pid_str, cmd_str = parts
        if not pid_str.isdigit():
            continue
        pid = int(pid_str)
        if pattern.search(cmd_str):
            matches.append({
                "processId": pid,
                "processString": cmd_str.strip()
            })

    # Optionally sort by PID
    matches.sort(key=lambda x: x["processId"])

    return jsonify(matches), 200

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)

